function removePlotIndexFromAccount(address account, uint256 fieldId, uint256 plotIndex) internal {
    AppStorage storage s = LibAppStorage.diamondStorage();
    uint256 i = findPlotIndexForAccount(account, fieldId, plotIndex);
    Field storage field = s.accts[account].fields[fieldId];
    field.plotIndexes[i] = field.plotIndexes[field.plotIndexes.length - 1];
    field.plotIndexes.pop();
}

function findPlotIndexForAccount(address account, uint256 fieldId, uint256 plotIndex) internal view returns (uint256 i) {
    AppStorage storage s = LibAppStorage.diamondStorage();
    Field storage field = s.accts[account].fields[fieldId];
    uint256[] memory plotIndexes = field.plotIndexes;   // full-array SLOAD copy
    uint256 length = plotIndexes.length;
    while (plotIndexes[i] != plotIndex) {                // O(n) linear scan
        i++;
        if (i >= length) { revert("Id not found"); }
    }
    return i;
}

